import apiClient from './client'

export interface SystemSettingsRead {
  public_server_url: string | null
  alert_detector_enabled: boolean
  metric_backend_health_check_at_startup: boolean
  local_agent_enabled: boolean
  log_dir: string
  backup_dir: string
  influxdb_url: string
  influxdb_org: string
  influxdb_bucket: string
  influxdb_retention_days: number
  user_session_max_age_days: number
  user_session_slide_days: number
  ai_self_optimization_enabled: boolean
  optimization_effect_track_days: number
}

export async function getSystemSettings(): Promise<SystemSettingsRead> {
  const response = await apiClient.get<SystemSettingsRead>('/v1/admin/settings')
  return response.data
}
